def png_data(p,max_dim=280):
 im=Image.open(p).convert('RGBA');im.thumbnail((max_dim,max_dim),resample=Image.Resampling.NEAREST if max(im.size)<=256 else Image.Resampling.LANCZOS)
 b=io.BytesIO(); im.save(b,format='PNG',optimize=True)
 return 'data:image/png;base64,'+base64.b64encode(b.getvalue()).decode()
def img(p,max_dim=700,cssclass='',alt=''):
 p=R/p if not str(p).startswith(str(R)) else Path(p)
 return f'<img class="{cssclass}" loading="lazy" src="{png_data(p,max_dim)}" alt="{html.escape(alt or p.stem.replace("_"," "))}">'
def gallery(files,cols=4,max_dim=235):
 return '<div class="gallery c'+str(cols)+'">'+''.join(f'<figure class="asset"><div class="artfield">{img(R/a["archivo"],max_dim,"pixel" if a["dimensiones"][0]<200 else "",a["archivo"])}</div><figcaption><b>{html.escape(Path(a["archivo"]).stem.replace("_"," "))}</b><small>{a["dimensiones"][0]} × {a["dimensiones"][1]} px · {html.escape(a["archivo"])}</small></figcaption></figure>' for a in files)+'</div>'
def section(code,intro,cols=4,max_dim=230):
 return f'<section id="{code.lower()}" class="section"><div class="secthead"><div><span class="eyebrow">ENCARGO {code}</span><h2>{html.escape(dict((x[0],x[1]) for x in series)[code])}</h2><p>{html.escape(intro)}</p></div><div class="pill">{len(bycode[code])} recursos</div></div>{gallery(bycode[code],cols,max_dim)}</section>'
